import sys

def max_sliding_brute(nums, k):
    return [max(nums[i:i + k]) for i in range(len(nums) - k + 1)]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n, k = int(data[0]), int(data[1])
    nums = list(map(int, data[2:2 + n]))
    print(' '.join(map(str, max_sliding_brute(nums, k))))

import sys
from collections import deque

def max_sliding_opt(nums, k):
    dq = deque()
    res = []
    for i, x in enumerate(nums):
        while dq and dq[-1] < x:
            dq.pop()
        dq.append(x)
        if i >= k and dq and dq[0] == nums[i - k]:
            dq.popleft()
        if i >= k - 1:
            res.append(dq[0])
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n, k = int(data[0]), int(data[1])
    nums = list(map(int, data[2:2 + n]))
    print(' '.join(map(str, max_sliding_opt(nums, k))))

import sys
from collections import deque

def max_sliding_best(nums, k):
    dq = deque()
    res = []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n, k = int(data[0]), int(data[1])
    nums = list(map(int, data[2:2 + n]))
    print(' '.join(map(str, max_sliding_best(nums, k))))
